import sys
import os
import xml.etree.ElementTree as ET
from datetime import datetime
import re

def evaluate_expression(expr, cells):
    def parse_expression(s):
        tokens = re.findall(r'(\d+\.?\d*|[a-zA-Z][a-zA-Z0-9_]*|[+\-*/()])', s)
        stack = []
        for token in tokens:
            if token.replace('.', '').isdigit():
                stack.append(float(token))
            elif token in cells:
                stack.append(cells[token])
            elif token == '(':
                stack.append(token)
            elif token == ')':
                while stack[-1] != '(':
                    stack.pop()
                stack.pop()  # Remove '('
            else:
                if len(stack) < 2:
                    raise ValueError(f"Invalid expression: {s}")
                b = stack.pop()
                a = stack.pop()
                if token == '+':
                    stack.append(a + b)
                elif token == '-':
                    stack.append(a - b)
                elif token == '*':
                    stack.append(a * b)
                elif token == '/':
                    stack.append(a / b)
        if len(stack) != 1:
            raise ValueError(f"Invalid expression: {s}")
        return stack[0]

    return parse_expression(expr)

def main():
    if len(sys.argv) != 2:
        sys.exit(1)

    xml_path = sys.argv[1]
    if not os.path.exists(xml_path):
        sys.exit(1)

    cache_path = os.path.splitext(xml_path)[0] + '.cache'
    xml_mod_time = os.path.getmtime(xml_path)
    cache_mod_time = 0

    if os.path.exists(cache_path):
        cache_mod_time = os.path.getmtime(cache_path)

    if cache_mod_time > xml_mod_time:
        with open(cache_path, 'r') as f:
            print(f.read())
        return

    tree = ET.parse(xml_path)
    root = tree.getroot()

    cells = {}
    for cell in root.findall('cell'):
        name = cell.attrib['name']
        expr = cell.text.strip()
        if expr:
            value = evaluate_expression(expr, cells)
            cells[name] = value

    for cell in root.findall('cell'):
        name = cell.attrib['name']
        value = cells[name]
        print(f"{name} = {value}")

    with open(cache_path, 'w') as f:
        for cell in root.findall('cell'):
            name = cell.attrib['name']
            value = cells[name]
            f.write(f"{name} = {value}\n")

if __name__ == '__main__':
    main()

