import sys
import os
import xml.etree.ElementTree as ET
from datetime import datetime

def evaluate_expression(expr, cells):
    try:
        return eval(expr, {}, cells)
    except:
        raise ValueError(f"Invalid expression: {expr}")

def process_sheet(xml_path):
    xml_root = ET.parse(xml_path).getroot()
    cells = {}
    cell_order = []

    for cell in xml_root.findall('cell'):
        name = cell.attrib['name']
        expr = cell.text.strip()
        cell_order.append(name)
        cells[name] = expr

    cache_path = os.path.join(os.path.dirname(xml_path), 'report.cache')

    if os.path.exists(cache_path):
        cache_mod_time = os.path.getmtime(cache_path)
        xml_mod_time = os.path.getmtime(xml_path)
        if cache_mod_time > xml_mod_time:
            with open(cache_path, 'r') as f:
                print(f.read())
            return

    for name in cell_order:
        expr = cells[name]
        try:
            value = evaluate_expression(expr, cells)
            cells[name] = value
        except ValueError as e:
            print(f"Error evaluating {name}: {e}", file=sys.stderr)
            sys.exit(1)

    with open(cache_path, 'w') as f:
        for name in cell_order:
            f.write(f"{name} = {cells[name]}\n")

    for name in cell_order:
        print(f"{name} = {cells[name]}")

if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("Usage: python sheet.py <path-to-xml>", file=sys.stderr)
        sys.exit(1)
    process_sheet(sys.argv[1])
